/**
 * Calculate Levenshtein distance between two strings
 * @param {string} s1 - First string
 * @param {string} s2 - Second string
 * @returns {number} - Levenshtein distance
 */
function levenshteinDistance(s1, s2) {
  const m = s1.length;
  const n = s2.length;

  // Create a matrix to store distances
  const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

  // Base cases
  for (let i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  // Fill the matrix
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = s1[i - 1] === s2[j - 1] ? 0 : 1;
      dp[i][j] = Math.min(
        dp[i - 1][j] + 1,      // deletion
        dp[i][j - 1] + 1,      // insertion
        dp[i - 1][j - 1] + cost // substitution
      );
    }
  }

  return dp[m][n];
}

/**
 * Find the closest matching property name from available properties
 * @param {string} missingProperty - The missing property name
 * @param {string[]} availableProperties - List of available property names
 * @returns {string|null} - Closest match or null
 */
function findClosestMatch(missingProperty, availableProperties) {
  let bestDistance = Infinity;
  let bestMatches = [];

  for (const prop of availableProperties) {
    const dist = levenshteinDistance(missingProperty, prop);
    if (dist < bestDistance) {
      bestDistance = dist;
      bestMatches = [prop];
    } else if (dist === bestDistance) {
      bestMatches.push(prop);
    }
  }

  // Only return a suggestion if the distance is 3 or less
  if (bestDistance > 3) {
    return null;
  }

  // If multiple ties, return the one that comes first alphabetically
  bestMatches.sort();
  return bestMatches[0];
}

