  return {
    /**
     * Diagnose a missing property binding error
     * @param {string} propertyName - The name of the property that failed to bind
     * @returns {object} - Diagnosis object
     */
    diagnoseMissingProperty(propertyName) {
      const hasProperty = availableProperties.indexOf(propertyName) !== -1;

      return {
        error: true,
        missingProperty: propertyName,
        availableProperties: availableProperties,
        suggestion: hasProperty ? null : findClosestMatch(propertyName, availableProperties)
